import pytest

from target import append_metric


def test_nested_dict_is_not_shared():
    original = {"name": "cpu", "tags": {"kind": "x"}}
    result = append_metric([], original)
    result[0]["tags"]["kind"] = "changed"
    assert original["tags"]["kind"] == "x"


def test_metric_object_is_not_reused():
    original = {"name": "cpu"}
    result = append_metric([], original)
    assert result[0] is not original


def test_existing_metrics_are_kept():
    assert append_metric([{"name": "mem"}], {"name": "cpu"}) == [
        {"name": "mem"},
        {"name": "cpu"},
    ]
